 * Character-level scanning for a single directive line. Every directive fits
 * on one line, so the lexer never needs to cross a line boundary.
 */

export class ParseError extends Error {}

export class Lexer {
  constructor(text) {
    this.text = text
    this.pos = 0
  }

  atEnd() {
    return this.pos >= this.text.length
  }

  peek() {
    return this.atEnd() ? undefined : this.text[this.pos]
  }

  advance() {
    this.pos++
  }

  isCommentChar() {
    const c = this.peek()
    return c === '#' || c === ';'
  }

  /** True when nothing meaningful remains on the line: end of text, or a comment. */
  atLineEnd() {
    return this.atEnd() || this.isCommentChar()
  }

  skipWS() {
    while (!this.atEnd() && (this.peek() === ' ' || this.peek() === '\t')) this.advance()
  }

  readBareRun(charsetRe) {
    const start = this.pos
    while (!this.atEnd() && charsetRe.test(this.peek())) this.advance()
    return this.text.slice(start, this.pos)
  }

  /**
   * Reads an unquoted value token: true/false, a number, or invalid text to
   * report. It stops at whitespace, a comma, or a closing bracket/brace, but
   * (per the spec) a comment marker with no whitespace before it is part of
   * the token instead of ending the line.
   */
  readValueWord() {
    const start = this.pos
    while (!this.atEnd()) {
      const c = this.peek()
      if (c === ' ' || c === '\t' || c === ',' || c === ']' || c === '}') break
      this.advance()
    }
    return this.text.slice(start, this.pos)
  }

  readBasicString() {
    this.advance() // opening "
    let out = ''
    for (;;) {
      if (this.atEnd()) throw new ParseError('unterminated string')
      const c = this.peek()
      if (c === '"') {
        this.advance()
        return out
      }
      if (c === '\\') {
        this.advance()
        if (this.atEnd()) throw new ParseError('unterminated string')
        const e = this.peek()
        if (e === '"') { out += '"'; this.advance() }
        else if (e === '\\') { out += '\\'; this.advance() }
        else if (e === 'n') { out += '\n'; this.advance() }
        else if (e === 't') { out += '\t'; this.advance() }
        else if (e === 'r') { out += '\r'; this.advance() }
        else if (e === '0') { out += '\0'; this.advance() }
        else if (e === 'u') {
          this.advance()
          const hex = this.text.slice(this.pos, this.pos + 4)
          if (!/^[0-9A-Fa-f]{4}$/.test(hex)) throw new ParseError('invalid escape \\u')
          out += String.fromCharCode(parseInt(hex, 16))
          this.pos += 4
        } else {
          throw new ParseError('invalid escape \\' + e)
        }
      } else {
        out += c
        this.advance()
      }
    }
  }

  readLiteralString() {
    this.advance() // opening '
    let out = ''
    for (;;) {
      if (this.atEnd()) throw new ParseError('unterminated string')
      const c = this.peek()
      if (c === "'") {
        this.advance()
        return out
      }
      out += c
      this.advance()
    }
  }
}
