{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-gYoO9i/src/model.js","content":"/**
 * The document tree the parser builds, and the small helpers both the parser
 * and the output modes share.
 */

export function makeTable(path) {
  return { kind: 'table', entries: new Map(), explicit: false, path }
}

export function makeAot(path) {
  return { kind: 'aot', items: [], path }
}

export function typeOf(node) {
  switch (node.kind) {
    case 'table': return 'table'
    case 'aot': return 'array'
    case 'array': return 'array'
    case 'string': return 'string'
    case 'integer': return 'integer'
    case 'float': return 'float'
    case 'boolean': return 'boolean'
    default: throw new Error('unknown node kind ' + node.kind)
  }
}

/** Ascending order by Unicode code point, as JS string comparison already gives us. */
export function compareKeys(a, b) {
  return a < b ? -1 : a > b ? 1 : 0
}
"}

