 * Parses the configuration document described by the task: one directive per
 * line, building the table tree that `output.js` renders.
 */

import { Lexer, ParseError } from './lexer.js'
import { makeTable, makeAot } from './model.js'

const NAME_CHARS = /[A-Za-z0-9_-]/
const DIGITS = '\\d+(?:_\\d+)*'
const INT_RE = new RegExp(`^[+-]?${DIGITS}$`)
const FLOAT_RE = new RegExp(`^[+-]?${DIGITS}(?:\\.${DIGITS})?(?:[eE][+-]?${DIGITS})?$`)

/** Parses the whole document text and returns the root table node. */
export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = makeTable([])
  root.explicit = true
  let current = root

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    try {
      current = processLine(lines[i], root, current)
    } catch (err) {
      if (err instanceof ParseError) {
        const wrapped = new Error(err.message)
        wrapped.line = lineNo
        throw wrapped
      }
      throw err
    }
  }

  return root
}

function processLine(lineText, root, current) {
  const lexer = new Lexer(lineText)
  lexer.skipWS()
  if (lexer.atLineEnd()) return current

  if (lexer.peek() === '[') {
    return processHeader(lexer, root)
  }

  processAssignment(lexer, current)
  return current
}

function processHeader(lexer, root) {
  lexer.advance() // consume '['
  let isArray = false
  if (lexer.peek() === '[') {
    lexer.advance()
    isArray = true
  }
  lexer.skipWS()
  const segments = parseDottedName(lexer)
  lexer.skipWS()

  requireBracket(lexer)
  if (isArray) requireBracket(lexer)

  lexer.skipWS()
  if (!lexer.atLineEnd()) {
    throw new ParseError('trailing text after a table header')
  }

  return isArray ? resolveArrayHeader(root, segments) : resolveTableHeader(root, segments)
}

function requireBracket(lexer) {
  if (lexer.peek() !== ']') throw new ParseError('unterminated table header')
  lexer.advance()
}

function processAssignment(lexer, current) {
  const segments = parseDottedName(lexer)
  lexer.skipWS()
  if (lexer.peek() !== '=') throw new ParseError('expected key = value')
  lexer.advance()
  lexer.skipWS()

  assignInto(current, segments, current.path, lexer)

  lexer.skipWS()
  if (!lexer.atLineEnd()) {
    throw new ParseError('trailing text after a value')
  }
}

function parseName(lexer) {
  lexer.skipWS()
  const c = lexer.peek()
  if (c === '"') return lexer.readBasicString()
  if (c === "'") return lexer.readLiteralString()
  const word = lexer.readBareRun(NAME_CHARS)
  if (word === '') throw new ParseError('expected a name')
  return word
}

function parseDottedName(lexer) {
  const segments = [parseName(lexer)]
  for (;;) {
    lexer.skipWS()
    if (lexer.peek() === '.') {
      lexer.advance()
      lexer.skipWS()
      segments.push(parseName(lexer))
    } else {
      break
    }
  }
  return segments
}

/** Walks all but the last segment from `root`, creating implicit tables as needed. */
function walkIntermediate(root, segments) {
  let container = root
  const pathSoFar = []
  for (let i = 0; i < segments.length - 1; i++) {
    const seg = segments[i]
    pathSoFar.push(seg)
    const existing = container.entries.get(seg)
    if (existing === undefined) {
      const t = makeTable(pathSoFar.slice())
      container.entries.set(seg, t)
      container = t
    } else if (existing.kind === 'table') {
      container = existing
    } else if (existing.kind === 'aot') {
      container = existing.items[existing.items.length - 1]
    } else {
      throw new ParseError(pathSoFar.join('.') + ' is not a table')
    }
  }
  return { container, pathSoFar }
}

/** Assigns a dotted key's value into `baseTable`, whose own path is `basePath`. */
function assignInto(baseTable, segments, basePath, lexer) {
  const start = walkIntermediate(baseTable, segments)
  const container = start.container
  const pathSoFar = basePath.concat(start.pathSoFar)
  const finalSeg = segments[segments.length - 1]
  pathSoFar.push(finalSeg)

  if (container.entries.has(finalSeg)) {
    throw new ParseError('key ' + pathSoFar.join('.') + ' is defined twice')
  }

  const value = parseValue(lexer, pathSoFar)
  container.entries.set(finalSeg, value)
}

function resolveTableHeader(root, segments) {
  const { container, pathSoFar } = walkIntermediate(root, segments)
  const seg = segments[segments.length - 1]
  pathSoFar.push(seg)
  const existing = container.entries.get(seg)

  if (existing === undefined) {
    const t = makeTable(pathSoFar.slice())
    t.explicit = true
    container.entries.set(seg, t)
    return t
  }
  if (existing.kind !== 'table') {
    throw new ParseError(pathSoFar.join('.') + ' is not a table')
  }
  if (existing.explicit) {
    throw new ParseError('table ' + pathSoFar.join('.') + ' is defined twice')
  }
  existing.explicit = true
  return existing
}

function resolveArrayHeader(root, segments) {
  const { container, pathSoFar } = walkIntermediate(root, segments)
  const seg = segments[segments.length - 1]
  pathSoFar.push(seg)
  const existing = container.entries.get(seg)

  let aot
  if (existing === undefined) {
    aot = makeAot(pathSoFar.slice())
    container.entries.set(seg, aot)
  } else if (existing.kind === 'aot') {
    aot = existing
  } else {
    throw new ParseError(pathSoFar.join('.') + ' is not an array of tables')
  }

  const t = makeTable(pathSoFar.slice())
  t.explicit = true
  aot.items.push(t)
  return t
}

function parseValue(lexer, pathPrefix) {
  lexer.skipWS()
  const c = lexer.peek()
  if (c === undefined || c === '#' || c === ';' || c === ',' || c === ']' || c === '}') {
    throw new ParseError('expected a value')
  }
  if (c === '"') return { kind: 'string', value: lexer.readBasicString() }
  if (c === "'") return { kind: 'string', value: lexer.readLiteralString() }
  if (c === '[') return parseArray(lexer, pathPrefix)
  if (c === '{') return parseInlineTable(lexer, pathPrefix)
  return parseBareValue(lexer)
}

function parseBareValue(lexer) {
  const word = lexer.readValueWord()
  if (word === 'true') return { kind: 'boolean', value: true }
  if (word === 'false') return { kind: 'boolean', value: false }
  if (INT_RE.test(word)) {
    return { kind: 'integer', value: Number(word.replace(/_/g, '')) }
  }
  if (FLOAT_RE.test(word)) {
    return { kind: 'float', value: Number(word.replace(/_/g, '')) }
  }
  throw new ParseError('invalid value ' + word)
}

function parseArray(lexer, pathPrefix) {
  lexer.advance() // consume '['
  const items = []
  for (;;) {
    lexer.skipWS()
    if (lexer.atLineEnd()) throw new ParseError('unterminated array')
    if (lexer.peek() === ']') {
      lexer.advance()
      break
    }
    items.push(parseValue(lexer, pathPrefix))
    lexer.skipWS()
    if (lexer.atLineEnd()) throw new ParseError('unterminated array')
    if (lexer.peek() === ',') {
      lexer.advance()
      continue
    }
    if (lexer.peek() === ']') {
      lexer.advance()
      break
    }
    throw new ParseError('unterminated array')
  }
  return { kind: 'array', items }
}

function parseInlineTable(lexer, pathPrefix) {
  lexer.advance() // consume '{'
  const table = makeTable(pathPrefix.slice())
  lexer.skipWS()
  if (lexer.atLineEnd()) throw new ParseError('unterminated inline table')
  if (lexer.peek() === '}') {
    lexer.advance()
    return table
  }

  for (;;) {
    lexer.skipWS()
    const segments = parseDottedName(lexer)
    lexer.skipWS()
    if (lexer.peek() !== '=') throw new ParseError('expected = in an inline table')
    lexer.advance()
    lexer.skipWS()

    assignInto(table, segments, pathPrefix, lexer)

    lexer.skipWS()
    if (lexer.atLineEnd()) throw new ParseError('unterminated inline table')
    if (lexer.peek() === ',') {
      lexer.advance()
      continue
    }
    if (lexer.peek() === '}') {
      lexer.advance()
      return table
    }
    throw new ParseError('unterminated inline table')
  }
}
"}

