 * Renders a parsed document tree (see `model.js`) as JSON or as a flat
 * listing of every node's path and type.
 */

import { typeOf, compareKeys } from './model.js'

/** Two-space-indented JSON, with object members in ascending key order. */
export function toJson(root) {
  return jsonValue(root, '') + '\n'
}

function jsonValue(node, indent) {
  switch (node.kind) {
    case 'string':
    case 'integer':
    case 'float':
    case 'boolean':
      return JSON.stringify(node.value)
    case 'array':
      return jsonArray(node.items, indent)
    case 'aot':
      return jsonArray(node.items, indent)
    case 'table':
      return jsonTable(node, indent)
    default:
      throw new Error('unknown node kind ' + node.kind)
  }
}

function jsonArray(items, indent) {
  if (items.length === 0) return '[]'
  const inner = indent + '  '
  const parts = items.map((item) => inner + jsonValue(item, inner))
  return '[\n' + parts.join(',\n') + '\n' + indent + ']'
}

function jsonTable(node, indent) {
  const keys = [...node.entries.keys()].sort(compareKeys)
  if (keys.length === 0) return '{}'
  const inner = indent + '  '
  const parts = keys.map((k) => inner + JSON.stringify(k) + ': ' + jsonValue(node.entries.get(k), inner))
  return '{\n' + parts.join(',\n') + '\n' + indent + '}'
}

/** One `<path> <type>` line per node below the root, depth first. */
export function toKeys(root) {
  const lines = []
  collectKeys(root, '', lines)
  return lines.length === 0 ? '' : lines.join('\n') + '\n'
}

function collectKeys(node, path, lines) {
  if (node.kind === 'table') {
    const keys = [...node.entries.keys()].sort(compareKeys)
    for (const k of keys) {
      const child = node.entries.get(k)
      const childPath = path === '' ? k : path + '.' + k
      lines.push(childPath + ' ' + typeOf(child))
      collectKeys(child, childPath, lines)
    }
  } else if (node.kind === 'array' || node.kind === 'aot') {
    node.items.forEach((child, i) => {
      const childPath = path + '[' + i + ']'
      lines.push(childPath + ' ' + typeOf(child))
      collectKeys(child, childPath, lines)
    })
  }
}
